import assert from 'node:assert/strict';
import {readFile,writeFile,copyFile,mkdir} from 'node:fs/promises';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {resolve,dirname} from 'node:path';
import {runCommand} from '../scripts/quality-process.mjs';
const root=resolve(import.meta.dirname,'..'),out=resolve(root,'results/search-live-host');
await mkdir(out,{recursive:true});
const path=resolve(root,'crates/xterm-addons/src/search/find.rs'),fixed=await readFile(path);
const hash=b=>createHash('sha256').update(b).digest('hex');
const old=execFileSync('git',['show','archive/Leonard458-complete:crates/xterm-addons/src/search/find.rs'],{cwd:root});
const commands=[];
async function run(label,browsers){
 const record=await runCommand(process.execPath,['scripts/browser-host-check.mjs'],{cwd:root,env:{...process.env,WASM_TEST:'wasm_search_addon',BROWSERS:browsers},log:resolve(out,label+'.log'),timeoutMs:240000});
 commands.push({label,...record});await writeFile(resolve(out,'browser-commands.json'),JSON.stringify(commands,null,2)+'\n');
 const report=JSON.parse(await readFile(resolve(root,'results/browser-host/wasm_search_addon-results.json'),'utf8'));
 await writeFile(resolve(out,label+'.json'),JSON.stringify(report,null,2)+'\n');
 const group=dirname(resolve(root,report.artifacts.bindings.path));
 const logs=dirname(group);
 for(const name of ['wasm_search_addon-build.log','wasm_search_addon-bindgen-version.log','wasm_search_addon-bindgen.log',...report.browsers.map(b=>'wasm_search_addon-'+b.name+'.log')]){
   await copyFile(resolve(logs,name),resolve(out,label+'-'+name));
 }
 const compiler=await readFile(resolve(root,report.artifacts.compiler.path));
 const fixture=await readFile(resolve(root,'crates/xterm-web/tests/fixtures/search-live-host.js'));
 assert.ok(compiler.includes(fixture),'exact shared fixture embedded in actual compiler artifact');
 return report;
}
let negative;
try{
 await writeFile(path,old);
 negative=await run('browser-negative','chromium');
 assert.equal(negative.status,'failed');
 assert.deepEqual(negative.browsers[0].counts,{passed:16,failed:1,ignored:0,filtered:0});
 assert.match(negative.browsers[0].output,/selection_uses_live_host_after_pre_match_reactivation.*FAIL/);
}finally{
 await writeFile(path,fixed);assert.equal(hash(await readFile(path)),hash(fixed));
 await writeFile(resolve(out,'browser-restore.json'),JSON.stringify({path:'crates/xterm-addons/src/search/find.rs',before:hash(fixed),restored:hash(await readFile(path)),old:hash(old)},null,2)+'\n');
 const report=await run('browser-fixed','chromium,firefox,webkit');
 assert.equal(report.status,'passed');
 for(const b of report.browsers)assert.deepEqual(b.counts,{passed:17,failed:0,ignored:0,filtered:0});
}
console.log('WASM old16PASS1FAIL, exact restore then17PASS each3engines');

