import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
import {readFile,writeFile,lstat} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {referenceIntegrity} from '../scripts/upstream-baseline-utils.mjs';
const archive='archive/Leonard458-complete';
const show=p=>execFileSync('git',['show',archive+':'+p],{maxBuffer:16000000});
const summary=JSON.parse(show('results/search-highlight-options/summary.json'));
const verified=[];
for(const p of summary.files){let bytes=show(p.path);if(p.path.endsWith('.md'))bytes=Buffer.from(bytes.toString().replaceAll('\r\n','\n'));const actual=createHash('sha256').update(bytes).digest('hex');assert.equal(actual,p.sha256,p.path);verified.push({path:p.path,sha256:actual});}
const manifest=JSON.parse(await readFile('docs/baseline/reference-manifest.json'));
const reference={private:referenceIntegrity('source_repo',manifest),original:referenceIntegrity('P:/workshop/Windows_Worshop/oira666/xterm-rust/source_repo',manifest)};
for(const r of Object.values(reference))assert.deepEqual(r.mismatches,[]);
let oldRootAbsent=false;try{await lstat('O:/xterm-rust-swarm-16/tmp/L458')}catch(e){if(e.code!=='ENOENT')throw e;oldRootAbsent=true;}
assert.ok(oldRootAbsent);
await writeFile('results/search-live-host/inheritance.json',JSON.stringify({archive,commit:execFileSync('git',['rev-parse',archive],{encoding:'utf8'}).trim(),verified,reference,oldRootAbsent},null,2)+'\n');
console.log('48 inherited pins,776x2 reference files verified; old458 absent');
